function SalesChart({sales,start}:{sales:Sale[];start:string}){
 const end=today(), from=start||(sales.map(s=>s.date).sort()[0]||end), span=Math.max(1,Math.round((Date.parse(end+'T12:00:00Z')-Date.parse(from+'T12:00:00Z'))/86400000)+1), count=Math.min(7,span);
 const data=Array.from({length:count},(_,i)=>{const a=new Date(from+'T12:00:00Z'),b=new Date(from+'T12:00:00Z');a.setUTCDate(a.getUTCDate()+Math.floor(i*span/count));b.setUTCDate(b.getUTCDate()+Math.floor((i+1)*span/count)-1);const low=a.toISOString().slice(0,10),date=b.toISOString().slice(0,10),list=sales.filter(s=>s.date>=low&&s.date<=date);return {date,value:list.reduce((a,s)=>a+total(s),0),profit:list.reduce((a,s)=>a+profit(s),0)};});
 const max=Math.max(...data.flatMap(d=>[d.value,d.profit]),10000),min=Math.min(...data.map(d=>d.profit),0);const y=(v:number)=>170-(v-min)/(max-min)*140;const pts=(key:'value'|'profit')=>data.map((d,i)=>`${62+i*(468/Math.max(1,count-1))},${y(d[key])}`).join(' ');
 return <div className="chart"><svg viewBox="0 0 580 215" role="img" aria-label="Gráfico da receita e lucro das vendas agrupados em intervalos iguais no período selecionado."><defs><linearGradient id="goldfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c59b45" stopOpacity=".16"/><stop offset="100%" stopColor="#c59b45" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return <g key={i}><line x1="60" x2="535" y1={y(v)} y2={y(v)} stroke="#eeece8" strokeDasharray="3 5"/><text x="3" y={y(v)+4} fill="#98948c" fontSize="10">{(v/100).toLocaleString('pt-BR',{maximumFractionDigits:0})}</text></g>;})}<polygon points={`62,${y(0)} ${pts('value')} 530,${y(0)}`} fill="url(#goldfill)"/><polyline points={pts('profit')} fill="none" stroke="#adb9af" strokeWidth="2.5" strokeLinejoin="round"/><polyline points={pts('value')} fill="none" stroke="#bc933e" strokeWidth="3" strokeLinejoin="round"/>{data.map((d,i)=><g key={i}><circle cx={62+i*(468/Math.max(1,count-1))} cy={y(d.value)} r="3.5" fill="#bc933e" stroke="white" strokeWidth="2"><title>{shortDate(d.date)}: receita {money(d.value)}, lucro {money(d.profit)}</title></circle><text x={62+i*(468/Math.max(1,count-1))} y="202" textAnchor="middle" fill="#96918a" fontSize="11">{shortDate(d.date).replace('.','')}</text></g>)}</svg></div>;
}
function DataForm({type,data:p,saving,onSubmit}:{type:string;data:any;saving:boolean;onSubmit:(d:any)=>void}){
 const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d:any=Object.fromEntries(new FormData(e.currentTarget));if(p?.id)d.id=p.id;for(const key of ['cost','price','wholesale','amount'])if(key in d)d[key]=Math.round(Number(d[key])*100);for(const key of ['stock','min','qty'])if(key in d)d[key]=Number(d[key]);onSubmit(d);};
 return <form onSubmit={submit}><div className="form-grid">
 {type==='product'&&<><div className="photo-selector full">{p?.image&&<img src={photoSrc(p.image)} alt={p.name+' · '+p.color}/>}<Field label="Foto de identificação da peça" name="image" value={p?.image||''}><option value="">Sem foto de referência</option>{catalog.map(c=><option key={c.id} value={c.image}>{c.name} · {c.color}</option>)}</Field></div><Field label="Nome da peça" name="name" value={p?.name} required/><Field label="Modelo / grupo de cores" name="model" value={p?.model||p?.name} required placeholder="Mesmo nome para todas as cores do modelo"/><Field label="Código SKU (único)" name="sku" value={p?.sku} required placeholder="Ex.: UZ-SHORT-PRETO-M"/><Field label="Categoria" name="category" value={p?.category||'Shorts'}>{categories.map(x=><option key={x}>{x}</option>)}</Field><Field label="Fornecedor" name="supplier" value={p?.supplier}/><Field label="Cor" name="color" value={p?.color} required/><Field label="Tamanho" name="size" value={p?.size||''} required><option value="">Selecione o tamanho</option>{['PP','P','M','G','GG','XG','Único','36','38','40','42','44','46','48'].map(x=><option key={x}>{x}</option>)}</Field><Field label="Custo unitário (R$)" name="cost" value={p?.cost!=null?p.cost/100:undefined} type="number" min={0} step="0.01" required/><Field label="Preço varejo (R$)" name="price" value={p?.price!=null?p.price/100:undefined} type="number" min={0.01} step="0.01" required/><Field label="Preço atacado (R$)" name="wholesale" value={p?.wholesale!=null?p.wholesale/100:undefined} type="number" min={0.01} step="0.01" required/>{!p?.id&&<Field label="Estoque inicial (peças)" name="stock" value={0} type="number" min={0} required/>}<Field label="Alerta com estoque até" name="min" value={p?.min??5} type="number" min={0} required/>{p?.id&&<p className="form-note">Estoque atual: {p.stock}. Use a movimentação para reposições ou ajustes. O custo editado vale para novas vendas; as anteriores mantêm o custo registrado.</p>}</>}
 {type==='customer'&&<><Field label="Nome do cliente" name="name" value={p?.name} required/><Field label="Telefone / WhatsApp" name="phone" value={p?.phone} placeholder="(85) 99999-9999"/><Field label="Cidade / UF" name="city" value={p?.city} placeholder="Fortaleza / CE"/><Field label="Tipo de cliente" name="kind" value={p?.kind||'Varejo'}><option>Varejo</option><option>Revendedor</option></Field></>}
 {type==='stock'&&<><div className="form-note full"><strong>{p.name} · {p.color} · {p.size}</strong><p>Estoque atual: {p.stock} peças. Use valor positivo para entrada e negativo para saída.</p></div><Field label="Quantidade do ajuste" name="qty" type="number" required step="1"/><Field label="Motivo da movimentação" name="reason" required placeholder="Ex.: Reposição, perda ou conferência"/></>}
 {type==='expense'&&<><Field label="Descrição" name="name" required/><Field label="Categoria" name="category">{['Aluguel','Equipe','Embalagem','Marketing','Impostos','Outros'].map(x=><option key={x}>{x}</option>)}</Field><Field label="Valor (R$)" name="amount" type="number" min={0.01} step="0.01" required/><Field label="Data" name="date" type="date" value={today()} required/><p className="form-note">Cadastre despesas operacionais. O custo das peças é descontado automaticamente quando elas são vendidas, evitando a contagem em dobro.</p></>}
 </div><div className="modal-actions"><button className="primary" disabled={saving}>{saving?'Salvando...':'Salvar registro'}<Check size={16}/></button></div></form>;
}
function SaleForm({store,saving,onSubmit}:{store:Store;saving:boolean;onSubmit:(d:any)=>void}){
 const [kind,setKind]=useState('Varejo'),[lines,setLines]=useState<{productId:string;qty:number}[]>([]),[discount,setDiscount]=useState('0'),[fee,setFee]=useState('0'),[freight,setFreight]=useState('0'),[shipping,setShipping]=useState('0'),[error,setError]=useState('');
 const cent=(s:string)=>Math.round(Number(s||0)*100);const count=lines.reduce((a,i)=>a+i.qty,0);const sub=lines.reduce((a,i)=>{const p=store.products.find(x=>x.id===i.productId)!;return a+i.qty*(kind==='Atacado'?p.wholesale:p.price);},0),t=sub-cent(discount)+cent(freight);
 const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!lines.length){setError('Adicione pelo menos uma peça.');return;}if(kind==='Atacado'&&count<10){setError('Atacado: selecione pelo menos 10 peças.');return;}const d=Object.fromEntries(new FormData(e.currentTarget));onSubmit({...d,kind,items:lines,discount:cent(discount),fee:cent(fee),freight:cent(freight),shippingCost:cent(shipping),paid:d.paid==='true'});};
 if(!store.products.some(p=>p.active&&p.stock>0))return <Empty title="Cadastre o estoque primeiro" text="Você precisa de uma peça ativa com estoque para registrar uma venda."/>;
 return <form onSubmit={submit}><div className="sale-tabs">{['Varejo','Atacado'].map(x=><button type="button" key={x} className={x===kind?'selected':''} onClick={()=>setKind(x)}>{x==='Atacado'?<Crown size={17}/>:<ShoppingBag size={17}/>} {x}</button>)}</div>{kind==='Atacado'&&<p className="atacado-note">Mínimo de 10 peças. Misture modelos, cores e tamanhos.</p>}<div className="form-grid"><Field label="Cliente" name="customerId"><option value="">Cliente avulso</option>{store.customers.map(c=><option key={c.id} value={c.id}>{c.name}{c.kind==='Revendedor'?' · Revendedor':''}</option>)}</Field><Field label="Data da venda" name="date" value={today()} type="date" required/></div><SaleVariantPicker products={store.products.filter(p=>p.active)} kind={kind} onAdd={id=>{setLines(old=>old.some(x=>x.productId===id)?old.map(x=>x.productId===id?{...x,qty:x.qty+1}:x):[...old,{productId:id,qty:1}]);}}/><div className="cart-items">{lines.map(i=>{const p=store.products.find(p=>p.id===i.productId)!;return <div className="cart-row" key={i.productId}><Garment p={p} small/><div><strong>{p.name}</strong><small>{p.color} · {p.size} · {money(kind==='Atacado'?p.wholesale:p.price)}</small></div><input aria-label={'Quantidade de '+p.name+' '+p.size} type="number" min={1} max={p.stock} required value={i.qty} onChange={e=>setLines(ls=>ls.map(l=>l.productId===i.productId?{...l,qty:Number(e.target.value)}:l))}/><button type="button" className="icon-btn" aria-label="Remover peça" onClick={()=>setLines(ls=>ls.filter(l=>l.productId!==i.productId))}><X size={16}/></button></div>;})}</div><div className="cart-subtotal"><span>{count} peças {kind==='Atacado'&&<Badge tone={count<10?'amber':'green'}>{count}/10 mínimo</Badge>}</span><strong>{money(sub)}</strong></div><div className="form-grid"><label className="field"><span>Desconto total (R$)</span><input type="number" min={0} max={sub/100} step="0.01" value={discount} onChange={e=>setDiscount(e.target.value)}/></label><label className="field"><span>Taxa de pagamento (R$)</span><input type="number" min={0} step="0.01" value={fee} onChange={e=>setFee(e.target.value)}/></label><label className="field"><span>Frete cobrado do cliente (R$)</span><input type="number" min={0} step="0.01" value={freight} onChange={e=>setFreight(e.target.value)}/></label><label className="field"><span>Custo do envio para a loja (R$)</span><input type="number" min={0} step="0.01" value={shipping} onChange={e=>setShipping(e.target.value)}/></label><Field label="Forma de pagamento" name="payment">{['Pix','Dinheiro','Cartão','Fiado'].map(x=><option key={x}>{x}</option>)}</Field><Field label="Situação do pagamento" name="paid"><option value="true">Recebido</option><option value="false">A receber</option></Field><Field label="Entrega" name="delivery">{['Retirada','A separar','Enviado','Entregue'].map(x=><option key={x}>{x}</option>)}</Field><Field label="Observação / endereço de envio" name="notes" placeholder="Opcional"/></div>{error&&<p role="alert" className="form-error">{error}</p>}<div className="sale-total"><span>Valor do lançamento<strong>{money(t)}</strong></span><button className="primary" disabled={saving||!lines.length}>{saving?'Salvando...':'Salvar lançamento'}<ArrowRight size={17}/></button></div></form>;
}
function SaleDetails({sale:s,saving,onAction,onCancel}:{sale:Sale;saving:boolean;onAction:(type:string,d:any)=>Promise<boolean>;onCancel:()=>void}){const [delivery,setDelivery]=useState(s.delivery),[tracking,setTracking]=useState(s.tracking);return <div className="sale-details"><div className="detail-title"><div><h3>{s.customerName}</h3><p>{shortDate(s.date)} · {s.kind} · {s.payment}</p></div><Badge tone={s.cancelled?'red':s.paid?'green':'amber'}>{s.cancelled?'Cancelada':s.paid?'Pago':'A receber'}</Badge></div>{s.items.map(i=><div className="detail-item" key={i.productId}><div><strong>{i.name}</strong><small>{i.variant} · {i.qty} peças × {money(i.price)}</small></div><strong>{money(i.qty*i.price)}</strong></div>)}<div className="waterfall compact">{[['Desconto',-s.discount],['Frete cobrado',s.freight],['Total da venda',total(s)],['Custo das peças',cost(s)],['Taxas e custo de envio',s.fee+s.shippingCost],['Lucro antes das despesas',profit(s)]].map(([k,v])=><div key={String(k)}><span>{k}</span><strong>{money(Number(v))}</strong></div>)}</div>{s.notes&&<p className="detail-notes">Observação: {s.notes}</p>}{!s.cancelled&&<><div className="form-grid"><label className="field"><span>Entrega</span><select value={delivery} onChange={e=>setDelivery(e.target.value)}>{['Retirada','A separar','Enviado','Entregue'].map(x=><option key={x}>{x}</option>)}</select></label><label className="field"><span>Código de rastreio</span><input value={tracking} maxLength={100} onChange={e=>setTracking(e.target.value)} placeholder="Opcional"/></label></div><div className="detail-actions"><button className="secondary" disabled={saving} onClick={()=>onAction('delivery',{id:s.id,delivery,tracking})}><Truck size={16}/>Salvar entrega</button>{!s.paid&&<button className="primary" disabled={saving} onClick={()=>onAction('paid',{id:s.id})}><Check size={16}/>Marcar recebido</button>}<button className="danger-link" disabled={saving} onClick={onCancel}>Cancelar venda</button></div></>}</div>;}
function PriceCalculator(){const [cost,setCost]=useState('50'),[margin,setMargin]=useState('40');const c=Number(cost),m=Number(margin),price=m<100&&m>=0?c/(1-m/100):0;return <div className="calculator"><label className="field"><span>Custo da peça (R$)</span><input type="number" min={0} step="0.01" value={cost} onChange={e=>setCost(e.target.value)}/></label><label className="field"><span>Margem desejada (%)</span><input type="number" min={0} max={99.9} step="0.1" value={margin} onChange={e=>setMargin(e.target.value)}/></label><div className="calculator-result"><small>Preço sugerido antes de taxas e despesas</small><strong>{m>=100||m<0?'Margem inválida':money(Math.round(price*100))}</strong><small>Preço = custo ÷ (1 − margem/100)</small></div></div>;}
