function SaleVariantPicker({products,kind,onAdd}:{products:Product[];kind:string;onAdd:(id:string)=>void}){const groups=groupModels(products),[key,setKey]=useState(''),[chosen,setChosen]=useState(''),[chosenId,setChosenId]=useState('');const g=groups.find(g=>g.key===key);const colors=g?modelColors(g):[],color=colors.includes(chosen)?chosen:colors[0],variants=g?.variants.filter(p=>p.color===color)||[],p=variants.find(p=>p.id===chosenId)||variants.find(p=>p.stock>0)||variants[0];return <div className="sale-variant-picker"><label className="field"><span>1. Modelo da peça</span><select value={key} onChange={e=>{setKey(e.target.value);setChosen('');setChosenId('');}}><option value="">Escolher modelo...</option>{groups.map(g=><option key={g.key} value={g.key} disabled={!g.variants.some(p=>p.stock>0)}>{g.name} · {modelColors(g).length} cores{!g.variants.some(p=>p.stock>0)?' · Esgotado':''}</option>)}</select></label>{g&&p&&<div className="sale-choice"><ModelPhoto item={p} colors={colors.length} onPrevious={()=>{setChosen(colors[(colors.indexOf(color)-1+colors.length)%colors.length]);setChosenId('');}} onNext={()=>{setChosen(colors[(colors.indexOf(color)+1)%colors.length]);setChosenId('');}}/><div><ColorControl colors={colors} value={color} onChange={c=>{setChosen(c);setChosenId('');}}/><label className="field"><span>3. Tamanho</span><select value={p.id} onChange={e=>setChosenId(e.target.value)}>{variants.map(v=><option key={v.id} value={v.id} disabled={v.stock<=0}>{v.size} · {v.stock>0?v.stock+' peças disponíveis':'Esgotado'} · {v.sku}</option>)}</select></label><div className="sale-choice-price"><strong>{money(kind==='Atacado'?p.wholesale:p.price)}</strong><small>{p.stock} peças disponíveis</small></div><button type="button" className="primary" disabled={p.stock<=0} onClick={()=>onAdd(p.id)}><Plus size={16}/>Adicionar esta variação</button></div></div>}</div>;}
function PhotoGallery({item:c}:{item:CatalogItem}){const photos=c.photos?.length?c.photos:[c.image],[index,setIndex]=useState(0),chosen=photos[index]||photos[0];return <div className="photo-detail"><div className="gallery-stage"><img src={photoSrc(chosen)} alt={c.name+' · '+c.color+' · foto '+(index+1)}/>{photos.length>1&&<><button className="photo-arrow previous" aria-label="Foto anterior" onClick={()=>setIndex((index-1+photos.length)%photos.length)}><ChevronLeft size={18}/></button><button className="photo-arrow next" aria-label="Próxima foto" onClick={()=>setIndex((index+1)%photos.length)}><ChevronRight size={18}/></button></>}</div>{photos.length>1&&<div className="gallery-thumbs" role="group" aria-label="Ângulos da peça">{photos.map((src,i)=><button key={src} className={i===index?'selected':''} aria-pressed={i===index} aria-label={'Ver foto '+(i+1)+' de '+c.name+' '+c.color} onClick={()=>setIndex(i)}><img src={photoSrc(src)} alt=""/></button>)}</div>}<p>{c.color} · {c.category}{photos.length>1?' · '+(index+1)+' de '+photos.length+' fotos':''}</p><a className="secondary" href={c.source} target="_blank" rel="noreferrer">Ver print de referência <ArrowUpRight size={15}/></a></div>;}
