 const colors=modelColors(g),[chosen,setChosen]=useState(colors[0]),[chosenId,setChosenId]=useState(''),[expanded,setExpanded]=useState(false),color=colors.includes(chosen)?chosen:colors[0],variants=g.variants.filter(p=>p.color===color),p=variants.find(p=>p.id===chosenId)||variants[0];
 const change=(c:string)=>{setChosen(c);setChosenId('');};const cycle=(n:number)=>change(colors[(colors.indexOf(color)+n+colors.length)%colors.length]);
