type AccessState={configured:boolean;authenticated:boolean;email:string|null;canSetup:boolean};
export default function AccessGate(){
 const [access,setAccess]=useState<AccessState|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 async function check(){setLoading(true);setError('');try{const r=await fetch('/api/auth',{cache:'no-store'}),d:any=await r.json();if(!r.ok)throw Error(d.error);setAccess(d);}catch(e){setError(e instanceof Error?e.message:'Não foi possível verificar o acesso.');}finally{setLoading(false);}}
 useEffect(()=>{check();},[]);
 async function logout(){try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});if(!r.ok)throw Error();setAccess(a=>a?{...a,authenticated:false,email:null}:a);}catch{setError('Não foi possível sair. Tente novamente.');}}
 if(access?.authenticated)return <>{error&&<div className="toast" role="alert">{error}<button onClick={()=>setError('')}>Fechar</button></div>}<App administratorEmail={access.email||''} onLogout={logout}/></>;
 return <div className="login-shell"><section className="login-brand-panel"><img src="/uzilai-logo.png" alt="Uzilai Jeans"/><span>UZILAI · GESTÃO INTERNA</span><h1>Administração<br/>da loja.</h1><p>Vendas, estoque e resultado financeiro em um painel exclusivo do proprietário.</p><div><ShieldCheck size={18}/> Acesso restrito ao administrador</div></section><section className="login-content"><div className="login-theme-toggle"><ThemeToggle/></div><div className="login-card"><div className="login-mobile-brand"><img src="/uzilai-logo.png" alt="Uzilai Jeans"/><strong>UZILAI</strong></div>{loading?<div className="login-loading">Verificando acesso...</div>:error&&!access?<><h2>Não foi possível abrir o acesso</h2><p>{error}</p><button className="primary" onClick={check}>Tentar novamente</button></>:!access?.configured&&!access?.canSetup?<><h2>Configuração inicial pendente</h2><p>O proprietário responsável pelo painel precisa definir o email e a senha do administrador antes de liberar o acesso.</p><button className="secondary" onClick={check}>Verificar novamente</button></>:<OwnerAccessForm setup={!access?.configured} onSuccess={check}/>}<small className="login-footnote">UZILAI · Painel administrativo privado</small></div></section></div>;
}
function OwnerAccessForm({setup,onSuccess}:{setup:boolean;onSuccess:()=>Promise<void>}){const [busy,setBusy]=useState(false),[error,setError]=useState(''),[show,setShow]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));if(setup&&d.password!==d.confirm){setError('As senhas não coincidem.');return;}setBusy(true);setError('');try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:setup?'setup':'login',email:d.email,password:d.password,setupKey:d.setupKey})}),data:any=await r.json();if(!r.ok)throw Error(data.error);form.reset();await onSuccess();}catch(e){setError(e instanceof Error?e.message:'Não foi possível acessar.');}finally{setBusy(false);}}
 return <><div className="eyebrow">{setup?'CONFIGURAÇÃO DO ADMINISTRADOR':'ACESSO DO PROPRIETÁRIO'}</div><h2>{setup?'Definir email e senha':'Entrar no painel'}</h2><p>{setup?'Configure a única conta de administrador da Uzilai. Os cadastros e lançamentos existentes serão mantidos.':'Use o email e a senha do administrador para acessar os registros da loja.'}</p><form onSubmit={submit}>{setup&&<label className="field"><span>Código de configuração inicial</span><input type="password" name="setupKey" autoComplete="off" required minLength={32} maxLength={256}/></label>}<label className="field"><span>Email do administrador</span><input type="email" name="email" autoComplete="username" required maxLength={254} placeholder="email@exemplo.com"/></label><label className="field password-field"><span>{setup?'Criar senha':'Senha'}</span><div><input type={show?'text':'password'} name="password" autoComplete={setup?'new-password':'current-password'} required minLength={setup?12:undefined} maxLength={128}/><button type="button" onClick={()=>setShow(!show)}>{show?'Ocultar':'Mostrar'}</button></div>{setup&&<small>Use pelo menos 12 caracteres.</small>}</label>{setup&&<label className="field"><span>Confirmar senha</span><input type="password" name="confirm" autoComplete="new-password" required minLength={12} maxLength={128}/></label>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="primary login-submit" disabled={busy}>{busy?'Aguarde...':setup?'Salvar acesso do administrador':'Entrar'}<ArrowRight size={17}/></button></form><p className="owner-only-note"><ShieldCheck size={14}/>{setup?'Este formulário configura o acesso do dono da loja.':'Não há cadastro aberto para clientes.'}</p></>;
}
function PasswordChangeForm(){const [busy,setBusy]=useState(false),[message,setMessage]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));if(d.password!==d.confirm){setMessage('As novas senhas não coincidem.');return;}setBusy(true);setMessage('');try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'change-password',currentPassword:d.currentPassword,password:d.password})}),data:any=await r.json();if(!r.ok)throw Error(data.error);form.reset();setMessage('Senha atualizada. Os outros acessos foram encerrados.');}catch(e){setMessage(e instanceof Error?e.message:'Não foi possível alterar a senha.');}finally{setBusy(false);}}return <div className="password-settings"><h3>Alterar senha do administrador</h3><form onSubmit={submit}><label className="field"><span>Senha atual</span><input type="password" name="currentPassword" autoComplete="current-password" required maxLength={128}/></label><label className="field"><span>Nova senha</span><input type="password" name="password" autoComplete="new-password" minLength={12} maxLength={128} required/></label><label className="field"><span>Confirmar nova senha</span><input type="password" name="confirm" autoComplete="new-password" minLength={12} maxLength={128} required/></label><button className="secondary" disabled={busy}>{busy?'Salvando...':'Atualizar senha'}</button></form>{message&&<p className="password-message" role="status">{message}</p>}</div>;}
